/// Outcome of a command run.
pub struct CmdOutcome {
    pub exit_code: i32,
    pub stdout: String,
    pub stderr: String,
    pub timed_out: bool,
    pub cancelled: bool,
}

/// Run a command to completion with optional streaming (`partial`), a timeout
/// (kills the child), and cancellation (kills the child when `cancel` fires).
/// stdout/stderr are read concurrently to avoid pipe deadlocks.
pub async fn run_command(
    mut cmd: Command,
    timeout: Option<Duration>,
    cancel: CancellationToken,
    partial: Option<Arc<dyn Fn(Option<String>, Option<String>) + Send + Sync>>,
) -> anyhow::Result<CmdOutcome> {
    let mut child = cmd
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped())
        .spawn()?;

    let stdout = child.stdout.take().expect("stdout is piped");
    let stderr = child.stderr.take().expect("stderr is piped");

    let partial_out = partial.clone();
    let out_task = tokio::spawn(async move {
        let mut buf = String::new();
        let mut lines = tokio::io::BufReader::new(stdout).lines();
        while let Ok(Some(line)) = lines.next_line().await {
            buf.push_str(&line);
            buf.push('\n');
            if let Some(cb) = &partial_out {
                cb(Some(line), None);
            }
        }
        buf
    });

    let partial_err = partial.clone();
    let err_task = tokio::spawn(async move {
        let mut buf = String::new();
        let mut lines = tokio::io::BufReader::new(stderr).lines();
        while let Ok(Some(line)) = lines.next_line().await {
            buf.push_str(&line);
            buf.push('\n');
            if let Some(cb) = &partial_err {
                cb(None, Some(line));
            }
        }
        buf
    });

    let mut outcome = CmdOutcome {
        exit_code: -1,
        stdout: String::new(),
        stderr: String::new(),
        timed_out: false,
        cancelled: false,
    };

    enum WaitResult {
        Done,
        TimedOut,
        Cancelled,
    }

    let result = tokio::select! {
        _ = cancel.cancelled() => WaitResult::Cancelled,
        result = async {
            let wait_fut = child.wait();
            tokio::pin!(wait_fut);
            let status = match timeout {
                Some(d) => tokio::time::timeout(d, &mut wait_fut).await,
                None => Ok(wait_fut.await),
            };
            match status {
                Ok(Ok(status)) => {
                    outcome.exit_code = status.code().unwrap_or(-1);
                    WaitResult::Done
                }
                Ok(Err(_)) => WaitResult::Done,
                Err(_) => WaitResult::TimedOut,
            }
        } => result,
    };

    match result {
        WaitResult::TimedOut => {
            let _ = child.kill().await;
            outcome.timed_out = true;
        }
        WaitResult::Cancelled => {
            let _ = child.kill().await;
            outcome.cancelled = true;
        }
        WaitResult::Done => {}
    }

    outcome.stdout = out_task.await.unwrap_or_default();
    outcome.stderr = err_task.await.unwrap_or_default();

    Ok(outcome)
}